/// Wavefront snapshot: who is placed in Will Bickford's wavefront map,
/// and where. Lookup for the claim flow (`/claim`, `/api/claim/lookup`).
///
/// The data is a build-time extract of wavefront.phext's index scroll —
/// `web/wavefront-snapshot.json`, regenerated by
/// `scripts/build_wavefront_snapshot.py` whenever the phext is
/// republished. The phext is the source of truth (wbic16/human@exo once
/// merged; the branch build until then); this module adds no placements.
///
/// A lookup answers one question: is this X (Twitter) handle in the map,
/// and at what coordinate and region? Handles match case-insensitively,
/// with or without the leading `@`, underscores intact — X handles are
/// `[A-Za-z0-9_]{1,15}` and half the map would break if `_` were eaten.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

const SNAPSHOT_JSON: &str = include_str!("../web/wavefront-snapshot.json");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Region {
    Hearth,
    Shoals,
    OpenWater,
}

impl Region {
    /// Display label, exactly as the phext's index words it.
    pub fn label(self) -> &'static str {
        match self {
            Region::Hearth => "the Hearth",
            Region::Shoals => "the Shoals",
            Region::OpenWater => "open water",
        }
    }

    fn parse(raw: &str) -> Option<Self> {
        match raw {
            "hearth" => Some(Region::Hearth),
            "shoals" => Some(Region::Shoals),
            "open_water" => Some(Region::OpenWater),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Placement {
    pub coordinate: String,
    pub region: Region,
    /// Moment label for multi-placement trails ("arrival", "rupture");
    /// empty for a single placement.
    pub label: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Person {
    /// Display handle, with `@`, in the map's own casing (e.g. `@eshear`).
    pub handle: String,
    pub name: String,
    pub placements: Vec<Placement>,
}

#[derive(Deserialize)]
struct SnapshotFile {
    people: Vec<SnapshotPerson>,
}

#[derive(Deserialize)]
struct SnapshotPerson {
    handle: String,
    name: String,
    placements: Vec<SnapshotPlacement>,
}

#[derive(Deserialize)]
struct SnapshotPlacement {
    coordinate: String,
    region: String,
    #[serde(default)]
    label: String,
}

fn snapshot() -> &'static HashMap<String, Person> {
    static SNAPSHOT: OnceLock<HashMap<String, Person>> = OnceLock::new();
    SNAPSHOT.get_or_init(|| {
        let file: SnapshotFile =
            serde_json::from_str(SNAPSHOT_JSON).expect("checked-in wavefront snapshot parses");
        let mut map = HashMap::with_capacity(file.people.len());
        for person in file.people {
            let Some(key) = normalize_handle(&person.handle) else { continue };
            let placements = person
                .placements
                .into_iter()
                .filter_map(|p| {
                    Some(Placement {
                        coordinate: p.coordinate,
                        region: Region::parse(&p.region)?,
                        label: p.label,
                    })
                })
                .collect::<Vec<_>>();
            if placements.is_empty() {
                continue;
            }
            map.insert(key, Person { handle: person.handle, name: person.name, placements });
        }
        map
    })
}

/// Reduce a user-typed handle to its lookup key: trimmed, one leading
/// `@` dropped, lowercased, underscores kept. None when what remains is
/// not a possible X handle — callers answer "not in the map", never a
/// filesystem or phext access, so hostile input ends here.
pub fn normalize_handle(raw: &str) -> Option<String> {
    let handle = raw.trim().strip_prefix('@').unwrap_or(raw.trim());
    if handle.is_empty() || handle.len() > 15 {
        return None;
    }
    if !handle.chars().all(|ch| ch.is_ascii_alphanumeric() || ch == '_') {
        return None;
    }
    Some(handle.to_ascii_lowercase())
}

/// The map's entry for a handle, however the visitor typed it.
pub fn lookup(raw: &str) -> Option<Person> {
    let key = normalize_handle(raw)?;
    snapshot().get(&key).cloned()
}

/// How many distinct accounts the snapshot holds.
pub fn snapshot_handles() -> usize {
    snapshot().len()
}

/// Total placements across all accounts (trails count twice).
pub fn snapshot_placements() -> usize {
    snapshot().values().map(|p| p.placements.len()).sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snapshot_matches_the_phext_accounting() {
        // wavefront.phext's index: 522 entries, 520 people. Entries are
        // keyed by account here, and Will holds two accounts (@wbic16,
        // his bot @wbic32): 521 handles, 522 placements.
        assert_eq!(snapshot_handles(), 521);
        assert_eq!(snapshot_placements(), 522);
    }

    #[test]
    fn lookup_is_case_and_at_insensitive_and_keeps_underscores() {
        for typed in ["eshear", "@eshear", "ESHEAR", "@Eshear", "  @eshear  "] {
            let person = lookup(typed).unwrap_or_else(|| panic!("{typed} should be in the map"));
            assert_eq!(person.handle, "@eshear");
            assert_eq!(person.name, "Emmett Shear");
            assert_eq!(person.placements.len(), 1);
            assert_eq!(person.placements[0].coordinate, "3.4.3/3.2.3/2.3.3");
            assert_eq!(person.placements[0].region, Region::OpenWater);
        }
        // Underscores are part of the handle, not decoration.
        let booch = lookup("@Grady_Booch").unwrap();
        assert_eq!(booch.placements[0].coordinate, "3.4.4/3.3.4/3.4.3");
        assert!(lookup("gradybooch").is_none());
    }

    #[test]
    fn trails_return_every_placement() {
        let orai = lookup("OraiAwake").unwrap();
        assert_eq!(orai.placements.len(), 2);
        assert_eq!(orai.placements[0].label, "arrival");
        assert_eq!(orai.placements[0].region, Region::Shoals);
        assert_eq!(orai.placements[1].label, "rupture");
        assert_eq!(orai.placements[1].coordinate, "4.3.1/1.1.1/1.5.1");

        let will = lookup("wbic16").unwrap();
        assert_eq!(will.placements[0].region, Region::Hearth);
        assert_eq!(will.placements[0].coordinate, "5.5.5/5.5.5/5.5.5");
    }

    #[test]
    fn unknown_and_malformed_handles_are_simply_not_in_the_map() {
        assert!(lookup("definitely_not_placed_9").is_none());
        for bad in ["", "@", "  ", "a b", "../etc/passwd", "handle!", "waytoolonghandle1", "@@x"] {
            assert!(lookup(bad).is_none(), "{bad:?} must not resolve");
            assert!(normalize_handle(bad).is_none(), "{bad:?} must not normalize");
        }
    }
}
